contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address other) public {
        require(other != address(this));

        uint256 otherBefore = c.balances(other); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 otherAfter = c.balances(other); if (__ESBMC_reverted()) return;
        assert(otherAfter == otherBefore);
    }
}

