contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address other) internal {
        vm.assume(other != address(this));
        uint256 otherBefore;
        try c.balances(other) returns (uint256 __r) { otherBefore = __r; } catch { return; }
